import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;

import 'models/models.dart';
import 'repositories/data_repository.dart';

/// Loads assets/demo/seed.json (generated by tool/generate_seed.py).
class DemoSeed {
  const DemoSeed._();

  static const assetPath = 'assets/demo/seed.json';
  static Map<String, dynamic>? _cache;

  static Future<Map<String, dynamic>> load() async {
    return _cache ??= jsonDecode(await rootBundle.loadString(assetPath)) as Map<String, dynamic>;
  }

  static List<DemoCredential> credentialsFrom(Map<String, dynamic> seed) =>
      ((seed['demo_credentials'] as List?) ?? const [])
          .map((e) => e as Map<String, dynamic>)
          .map((e) => DemoCredential(
                role: UserRole.parse(e['role'] as String?),
                name: e['name'] as String,
                email: e['email'] as String,
                password: e['password'] as String,
              ))
          .toList();
}
